def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a datetime.timedelta instance
    :type value: datetime.timedelta
    :return: total seconds as a float, or None if value is None
    :raises TypeError: if value is not a datetime.timedelta
    """
    if value is None:
        return None

    # Import here to avoid a global dependency if the function is never used
    try:
        from datetime import timedelta
    except ImportError as exc:
        raise ImportError("datetime module is required for dehydrate_timedelta") from exc

    if not isinstance(value, timedelta):
        raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")

    try:
        # Python 3.3+ provides total_seconds()
        return value.total_seconds()
    except AttributeError:
        # Fallback for older Python versions
        return (value.days * 86400 + value.seconds) + value.microseconds / 1_000_000"""

