def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: str
    """
    # Allow None to pass through unchanged
    if value is None:
        return None

    # Try to use an existing isoformat method
    try:
        return value.isoformat()
    except Exception:
        pass

    # Try to build a string from common time attributes
    try:
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second", 0)
        micro = getattr(value, "microsecond", 0)
        if micro:
            return f"{hour:02}:{minute:02}:{second:02}.{micro:06}"
        return f"{hour:02}:{minute:02}:{second:02}"
    except Exception:
        pass

    # If the value is already a string, return it
    if isinstance(value, str):
        return value

    raise TypeError("value must be a time-like object or string")

