def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        return {"x": value.x, "y": value.y}
    except AttributeError as e:
        raise ValueError(f"Expected a Point with 'x' and 'y' attributes, got: {value}") from e

