def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # If the object is dict-like, use its keys
    try:
        if isinstance(self, dict):
            return list(self.keys())
    except Exception:
        pass

    # If a dedicated record attribute exists, use that
    for attr in ('record', '_record', 'data'):
        if hasattr(self, attr):
            try:
                return list(getattr(self, attr).keys())
            except Exception:
                continue

    # Fallback: return the object's attribute names
    try:
        return list(self.__dict__.keys())
    except Exception:
        return []

