def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values.
    if not keys:
        # Try dict-like interface
        try:
            return list(self.values())
        except AttributeError:
            # Fall back to iterable of values
            if hasattr(self, '__iter__'):
                return [v for v in self]
            raise TypeError("The object does not provide a values() method or is not iterable")

    # Otherwise, build a list of requested values
    result = []
    for k in keys:
        if isinstance(k, int):
            # Treat k as an index into the value list
            try:
                vals = list(self.values())
            except AttributeError:
                if hasattr(self, '__iter__'):
                    vals = list(self)
                else:
                    raise TypeError("Indices can only be used with dict-like or iterable objects")
            try:
                result.append(vals[k])
            except IndexError as exc:
                raise KeyError(f"Index {k} out of range in record") from exc
        else:
            # Treat k as a key
            try:
                result.append(self[k])
            except Exception as exc:
                # Try a dict conversion for safety
                try:
                    result.append(dict(self)[k])
                except Exception as exc2:
                    raise KeyError(f"Key '{k}' not found in record") from exc2
    return result

