def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Try to obtain the field names and values from the record.
    try:
        fields = getattr(self, "_fields")
    except AttributeError:
        # Fallback: if object behaves like a mapping, use its keys
        try:
            fields = list(self.keys())
        except Exception:
            fields = []

    try:
        values = getattr(self, "_values")
    except AttributeError:
        # Fallback: if object behaves like a sequence of values
        try:
            values = list(self.values())
        except Exception:
            values = []

    # Build a base dictionary mapping field name to value.
    base = dict(zip(fields, values))

    # If no specific keys requested, return the entire mapping.
    if not keys:
        return dict(base)

    result = {}
    for key in keys:
        # Determine whether key is an integer index.
        is_index = False
        try:
            idx = int(key)
            is_index = True
        except Exception:
            is_index = False

        if is_index:
            if idx < 0 or idx >= len(values):
                raise IndexError(f"Index {idx} out of range for record with {len(values)} values")
            # Get the corresponding field name, if available.
            if idx < len(fields):
                field_name = fields[idx]
                result[field_name] = values[idx]
            else:
                # No field name for this index; skip or use numeric key.
                result[f"field_{idx}"] = values[idx]
        else:
            # Treat key as field name.
            if key in base:
                result[key] = base[key]
            else:
                # Field name not present: insert None per specification.
                result[key] = None

    return result

