def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Appends a BEGIN message to the output queue.

    Parameters:
        mode (str): access mode for routing - "READ" or "WRITE" (default)
        bookmarks (iterable): bookmark values after which this transaction should begin
        metadata (dict): custom metadata dictionary to attach to the transaction
        timeout (float): timeout for transaction execution (seconds)
        db (str): name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        imp_user (str): the user to impersonate
            Requires Bolt 4.4+
        dehydration_hooks (dict): Hooks to dehydrate types (dict from type
            (class) to dehydration function). Dehydration functions receive
            the value and return an object of type understood by packstream.
        hydration_hooks (dict): Hooks to hydrate types (mapping from type
            (class) to dehydration function). Dehydration functions receive
            the value of type understood by packstream and are free to return any
            object.
        handlers: handler functions passed into the returned Response object
    Returns:
        Response object
    """
    # Validate mode
    if mode is not None:
        mode_val = mode.upper()
        if mode_val not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")
    else:
        mode_val = None

    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks_val = list(bookmarks)
        except Exception as exc:
            raise TypeError("bookmarks must be an iterable") from exc
    else:
        bookmarks_val = None

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    # Merge hooks into the connection's settings
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        self.dehydration_hooks.update(dehydration_hooks)
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        self.hydration_hooks.update(hydration_hooks)

    # Build the payload for the BEGIN packet
    payload = {}
    if mode_val:
        payload["mode"] = mode_val
    if bookmarks_val:
        payload["bookmarks"] = bookmarks_val
    if metadata:
        payload["metadata"] = metadata
    if timeout:
        payload["timeout"] = timeout
    if db:
        payload["database"] = db
    if imp_user:
        payload["impersonated_user"] = imp_user

    # Send the BEGIN packet
    try:
        self._enqueue_packet(self.BEGIN, payload)
    except AttributeError as exc:
        raise RuntimeError("Unable to enqueue BEGIN packet") from exc

    # Return the response object
    return Response(self, **handlers)

