def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate arguments
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Ensure field definitions are (name, type) tuples
    field_names = []
    for entry in fields:
        if not (isinstance(entry, tuple) and len(entry) == 2):
            raise ValueError("Each field must be a (name, type) tuple")
        fname, _ = entry
        if not isinstance(fname, str) or not fname.isidentifier():
            raise ValueError(f"Invalid field name: {fname}")
        field_names.append(fname)

    # Base point class (try to import from shapely, else a minimal fallback)
    try:
        from shapely.geometry import Point as _BasePoint
    except Exception:
        class _BasePoint:
            def __init__(self, x, y, z=None):
                self.x = x
                self.y = y
                self.z = z

    def __init__(self, x, y, z=None, srid=None, **kwargs):
        super(self.__class__, self).__init__(x, y, z)
        for fname, _ in fields:
            setattr(self, fname, kwargs.get(fname))
        # Resolve srid to numeric if a string is provided
        if isinstance(srid, str):
            self.srid = srid_map.get(srid)
        else:
            self.srid = srid

    def __repr__(self):
        # Use the class name that was passed in
        return f"<{name} id={getattr(self, 'id', None)} x={self.x} y={self.y} srid={self.srid}>"

    attrs = {
        "__init__": __init__,
        "__repr__": __repr__,
        "__slots__": field_names + ["srid"],
    }

    return type(name, (_BasePoint,), attrs)

