def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Expected a string, got %r" % type(s).__name__)
    if not s:
        return ()
    # Replace common separators with a period to simplify splitting
    s_clean = s.replace('-', '.').replace('_', '.')
    parts: list[int] = []
    for part in s_clean.split('.'):
        if part.isdigit():
            parts.append(int(part))
        else:
            # extract leading numeric portion
            num_str = ''
            for ch in part:
                if ch.isdigit():
                    num_str += ch
                else:
                    break
            if num_str:
                parts.append(int(num_str))
            else:
                # non‑numeric segment, treat as zero
                parts.append(0)
    return tuple(parts)

