def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            return func  # do nothing

        cache = {}
        recency = []

        def _make_key(args, kwd):
            key = args
            if kwd:
                items = tuple(sorted(kwd.items()))
            else:
                items = ()
            if typed:
                key = args + tuple(type(v) for v in args)
                items = items + tuple((k, type(v)) for k, v in sorted(kwd.items()))
            return (key, items)

        def wrapper(*args, **kwd):
            key = _make_key(args, kwd)
            entry = cache.get(key)
            now = timer()
            if entry is not None:
                value, expire = entry
                if expire > now:
                    # Move key to end to denote recent use
                    try:
                        recency.remove(key)
                    except ValueError:
                        pass
                    recency.append(key)
                    return value
                else:
                    # Expired
                    del cache[key]
                    try:
                        recency.remove(key)
                    except ValueError:
                        pass
            # compute new value
            result = func(*args, **kwd)
            cache[key] = (result, now + ttl)
            recency.append(key)
            # Evict oldest if necessary
            if len(cache) > maxsize:
                oldest = recency.pop(0)
                cache.pop(oldest, None)
            return result

        return wrapper
    return decorator

