def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of types")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class")
        # Skip if already present
        if cls in result:
            continue
        # Check if this class is a subclass of any already in result
        if any(issubclass(cls, existing) for existing in result):
            continue
        # Remove any existing classes that are subclasses of this new class
        result = [existing for existing in result if not issubclass(existing, cls)]
        result.append(cls)
    return result

