def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # If the item looks like a Declaration (has interface and implements)
        if hasattr(item, "interface") and hasattr(item, "implements"):
            output.append(item.interface)
            if item.implements:
                # `implements` might be a single object or an iterable of objects
                if isinstance(item.implements, (list, tuple)):
                    output.extend(item.implements)
                else:
                    output.append(item.implements)

        # If the item is a tuple, treat it as a sequence of interfaces/specs
        elif isinstance(item, tuple):
            output.extend(item)

        # Otherwise, assume it's an individual interface or spec
        else:
            output.append(item)

    return output

