def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Sanity checks
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object lacks 'edges' attribute")
    if not hasattr(self, "data") and not hasattr(self, "buckets"):
        raise AttributeError("Histogram object lacks storage attribute ('data' or 'buckets')")
    if not isinstance(coord, (list, tuple)):
        raise TypeError("coord must be a sequence of coordinates")

    # Dimension check
    if len(coord) != len(self.edges):
        raise ValueError(f"Coordinate dimensionality ({len(coord)}) does not match histogram ({len(self.edges)})")

    # Find bin indices for each dimension
    bin_indices = []
    for val, edge in zip(coord, self.edges):
        # If coordinate is outside the defined edges, ignore it
        if val < edge[0] or val > edge[-1]:
            return
        # Find the bin index
        # Note: assumes edges are sorted in ascending order
        idx = None
        for i in range(len(edge) - 1):
            if edge[i] <= val < edge[i + 1]:
                idx = i
                break
        # If value equals the last edge value, it falls into the last bin
        if idx is None and val == edge[-1] and len(edge) > 1:
            idx = len(edge) - 2
        if idx is None:
            return  # Outside or malformed edges
        bin_indices.append(idx)

    bin_tuple = tuple(bin_indices)

    # Update histogram storage
    if hasattr(self, "data"):
        try:
            self.data[bin_tuple] += weight
        except Exception as exc:
            raise RuntimeError(f"Failed to update histogram data: {exc}") from exc
    else:
        # Use sparse dictionary representation
        self.buckets[bin_tuple] = self.buckets.get(bin_tuple, 0) + weight

