    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re
    # Convert non-string values to string for validation
    if not isinstance(value, str):
        value = str(value)

    # Retrieve the regular expression from the surrounding scope
    try:
        pattern = regex
    except NameError:
        raise ValidationError("No regular expression defined for validation.")

    # Compile string patterns if necessary
    if isinstance(pattern, str):
        try:
