        except re.error as exc:
            raise ValidationError(f"Invalid regular expression '{pattern}': {exc}")

    # Ensure the pattern supports fullmatch (Python ≥3.4)
    matched = pattern.fullmatch(value) if hasattr(pattern, "fullmatch") else pattern.match(value)
