def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic guard against a missing application object
    if not hasattr(app, "spec"):
        # nothing to do if no spec attribute
        return

    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        # nothing to do if no manifest defined
        return

    # Try to obtain the resources dictionary or iterable
    resources = getattr(manifest, "resources", None)
    if resources is None:
        # Support a case where the manifest itself is a mapping of resources
        resources = manifest

    # Iterate over resources and set a default observer schema when missing
    for key, resource in list(resources.items() if isinstance(resources, dict) else enumerate(resources)):
        try:
            # Resource may be a dict or an object instance
            if isinstance(resource, dict):
                if not resource.get("observer_schema"):
                    resource["observer_schema"] = {"fields": []}
            else:
                if not getattr(resource, "observer_schema", None):
                    setattr(resource, "observer_schema", {"fields": []})
        except Exception:
            # Skip problematic entries but continue processing
            continue

