        if not isinstance(inventory.documents, (list, tuple)):
            raise TypeError("inventory.documents must be a list or tuple.")

        # Determine spec version to use for validation
        spec_version_to_use = self.spec_version
        if extract_spec_version:
            # Try to extract version string from inventory.type if it's present and valid
            inv_type = getattr(inventory, "type", None)
            if inv_type and isinstance(inv_type, str):
                # Expected format: something like "fl-1.2" or "foLiA-1.2"
                try:
                    # Split on the last dash or colon and take the last segment
                    if "-" in inv_type:
                        part = inv_type.rsplit("-", 1)[-1]
                    elif ":" in inv_type:
                        part = inv_type.rsplit(":", 1)[-1]
                    else:
                        part = inv_type
                    # Strip any leading/trailing whitespace
                    part = part.strip()
                    # Quick validation: it should look like "X.Y" or "X.Y.Z"
                    if part and (part.count(".") >= 1):
                        spec_version_to_use = part
                except Exception:
                    # Ignore extraction errors; will fall back to default
                    pass

        errors = []

        # Example validation: each document must have a unique id and a non-empty title
        seen_ids = set()
        for idx, doc in enumerate(inventory.documents):
            if not hasattr(doc, "id") or not doc.id:
                errors.append(f"Document at index {idx} is missing a valid 'id' attribute.")
                continue
            if doc.id in seen_ids:
                errors.append(f"Duplicate document id '{doc.id}' found.")
            else:
                seen_ids.add(doc.id)
            if not hasattr(doc, "title") or not doc.title:
                errors.append(f"Document with id '{doc.id}' is missing a 'title' attribute.")
            # You can add more checks here based on spec_version_to_use if needed

        if errors:
            # Log or handle errors as needed; here we simply raise an exception
            error_msg = "Inventory validation failed:\n" + "\n".join(errors)
            raise ValueError(error_msg)

        # If we reach here, the inventory is considered valid
        return True

