def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Ensure manifest_files is a dictionary of digest -> entry information
        if not isinstance(manifest_files, dict):
            raise TypeError("manifest_files must be a dict mapping digest values to entries")
        if not isinstance(digests_used, (set, list, tuple)):
            raise TypeError("digests_used must be an iterable of digest strings")

        missing = [d for d in digests_used if d not in manifest_files]
        if missing:
            raise ValueError(f"Missing digests in manifest: {', '.join(missing)}")

        # Optional: warn about digests that are present in the manifest but not used
        unused = [d for d in manifest_files if d not in digests_used]
        if unused:
            try:
                # If a logger is available use it; otherwise just print a warning
                logger = getattr(self, "logger", None)
                message = f"Unused digests in manifest: {', '.join(unused)}"
                if logger and hasattr(logger, "warning"):
                    logger.warning(message)
                else:
                    print(f"WARNING: {message}", file=sys.stderr)
            except Exception:
                # ignore any logger errors
                pass

        # The checks passed; return True for convenience
        return True

