def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict mapping file names to checksum info")
    try:
        file_set = set(manifest_files)
    except TypeError as exc:
        raise TypeError("manifest_files must be an iterable of filenames") from exc

    import re
    hex_re = re.compile(r'^[0-9a-fA-F]+$')
    for fname, checks in fixity.items():
        if fname not in file_set:
            raise ValueError(f"Fixity references unknown file '{fname}' not listed in the manifest.")
        if not isinstance(checks, dict):
            raise TypeError(f"Checksums for file '{fname}' should be a dict")
        for alg, val in checks.items():
            if not isinstance(alg, str):
                raise TypeError(f"Checksum algorithm name must be a string, got {alg!r}")
            if not isinstance(val, str):
                raise TypeError(f"Checksum value for file '{fname}', algorithm '{alg}' must be a string")
            if not hex_re.match(val):
                raise ValueError(f"Checksum value for file '{fname}', algorithm '{alg}' is not valid hex.")
            # Basic length checks for common algorithms
            if alg.lower() == 'sha256' and len(val) != 64:
                raise ValueError(f"Checksum for file '{fname}' using SHA256 should be 64 hex digits.")
            if alg.lower() == 'md5' and len(val) != 32:
                raise ValueError(f"Checksum for file '{fname}' using MD5 should be 32 hex digits.")
    return True

