def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a str, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The specified folder does not exist: {folder}")

    package_data = {}
    try:
        for root, dirs, files in os.walk(folder):
            for fname in files:
                # Skip hidden files
                if fname.startswith('.'):
                    continue
                file_path = os.path.join(root, fname)
                try:
                    rel_path = os.path.relpath(file_path, folder)
                except Exception:
                    # Fallback to absolute path if rel error
                    rel_path = file_path
                stem, ext = os.path.splitext(fname)
                ext = ext.lower()

                if stem not in package_data:
                    package_data[stem] = {}
                # Read content if possible; if binary or unreadable, store None
                content = None
                try:
                    with open(file_path, 'r', encoding='utf-8') as fh:
                        content = fh.read()
                except Exception:
                    # Might be a binary or unsupported encoding
                    pass
                package_data[stem][ext] = {
                    'path': rel_path,
                    'content': content
                }
    except Exception as e:
        raise RuntimeError(f"Error while exploring folder '{folder}': {e}") from e

    return package_data

