def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        Mapping from XML basename to a dict of file paths and their data
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, "r") as z:
            # First pass: find XML files and record their basenames
            xml_basenames = {}
            for info in z.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith(".xml"):
                    basename, _ = os.path.splitext(os.path.basename(info.filename))
                    xml_basenames[basename] = info.filename

            if not xml_basenames:
                return packages  # no XML files found

            # Second pass: group every file by the basename of its XML counterpart
            for info in z.infolist():
                if info.is_dir():
                    continue
                basename, _ = os.path.splitext(os.path.basename(info.filename))
                if basename not in xml_basenames:
                    # Skip files without a matching XML file
                    continue
                try:
                    data = z.read(info.filename)
                except KeyError as exc:
                    raise zipfile.BadZipFile(
                        f"Failed to read {info.filename} from {zip_path}"
                    ) from exc
                packages.setdefault(basename, {})[info.filename] = data

    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Bad or corrupted zip file: {zip_path}") from exc

    return packages

