def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores válidos incluem:
        5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
        25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
        s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1,
        suppl, suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Get text from the element
    if issue is None:
        return (None, None)
    if hasattr(issue, "text"):
        text = issue.text or ""
    elif hasattr(issue, "get_text"):
        try:
            text = issue.get_text() or ""
        except Exception:
            text = str(issue) or ""
    else:
        text = str(issue) or ""

    text = text.strip()
    if not text:
        return (None, None)

    import re
    # Extract number part (supports optional range like "2-5")
    number_match = re.search(r'(?i)\b(\d+(?:-\d+)?)\b', text)
    number = number_match.group(1) if number_match else None

    # Remove the extracted number from the text
    suppl_part = text
    if number_match:
        suppl_part = text[:number_match.start()] + text[number_match.end():]
    suppl_part = suppl_part.strip()

    # Clean up surrounding punctuation and parentheses
    suppl_part = suppl_part.strip("().,[]{}<>")
    suppl_part = suppl_part.strip()

    if not suppl_part:
        suppl_part = None

    return (number, suppl_part)

