def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    parts = [f"{indent_str}<{self.__class__.__name__}"]
    try:
        # Get attributes either from __dict__ or __slots__
        if hasattr(self, "__dict__"):
            attrs = dict(self.__dict__)
        elif hasattr(self, "__slots__"):
            attrs = {slot: getattr(self, slot) for slot in self.__slots__}
        else:
            attrs = {}
    except Exception:
        attrs = {}

    for name, value in attrs.items():
        try:
            if hasattr(value, "pretty") and callable(value.pretty):
                parts.append("\n" + value.pretty(indent + 2, debug))
            elif isinstance(value, (list, tuple)):
                parts.append(f"\n{indent_str}  {name}: [")
                for item in value:
                    if hasattr(item, "pretty"):
                        parts.append("\n" + item.pretty(indent + 4, debug))
                    else:
                        parts.append("\n" + (' ' * (indent + 4)) + repr(item))
                parts.append(f"\n{indent_str}  ]")
            elif isinstance(value, dict):
                parts.append(f"\n{indent_str}  {name}: {{")
                for dk, dv in value.items():
                    if hasattr(dv, "pretty"):
                        parts.append("\n" + dv.pretty(indent + 4, debug))
                    else:
                        parts.append("\n" + (' ' * (indent + 4)) + f"{dk}: {repr(dv)}")
                parts.append(f"\n{indent_str}  }}")
            else:
                if debug:
                    parts.append(f"\n{indent_str}  {name} ({type(value).__name__}): {repr(value)}")
                else:
                    parts.append(f"\n{indent_str}  {name}: {repr(value)}")
        except Exception:
            parts.append(f"\n{indent_str}  {name}: <error>")

    parts.append(f"\n{indent_str}</{self.__class__.__name__}>")
    return ''.join(parts)

