def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess, sys
    versions = {}
    # Determine package name from module namespace or environment
    try:
        pkg_name = __package__ or __name__.split('.')[0]
    except Exception:
        pkg_name = None
    # Attempt to get distribution version via importlib.metadata
    try:
        from importlib import metadata
    except ImportError:
        try:
            import pkg_resources
            metadata = pkg_resources
        except ImportError:
            metadata = None
    if metadata and pkg_name:
        try:
            if hasattr(metadata, 'version'):
                versions['version'] = metadata.version(pkg_name)
            elif hasattr(metadata, 'get_distribution'):
                versions['version'] = metadata.get_distribution(pkg_name).version
        except Exception:
            pass
    # Attempt to get git commit hash
    try:
        commit = subprocess.check_output(
            ['git', 'rev-parse', 'HEAD'],
            stderr=subprocess.DEVNULL,
            cwd=sys.path[0]
        )
        versions['commit'] = commit.decode('utf-8').strip()
    except Exception:
        pass
    if not versions:
        versions = {'version': 'unknown'}
    return versions

