def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _walk(node):
        nonlocal num_objects, good_objects
        num_objects += 1
        good = True

        # Validate the node itself if requested
        if validate_objects:
            try:
                validate_method = getattr(node, "validate", None)
                if callable(validate_method):
                    validate_method()
            except Exception as e:
                good = False
                if show_warnings:
                    print(f"Warning: validation failed for object {node!r}: {e}")

        # Check digest if requested
        if check_digests:
            try:
                # Prefer an explicit check_digest method
                if hasattr(node, "check_digest") and callable(node.check_digest):
                    node.check_digest()
                # Else if a digest attribute exists, assume verification method exists
                elif hasattr(node, "digest"):
                    # If there is a method to verify the digest; try calling it
                    verify_method = getattr(node, "verify_digest", None)
                    if callable(verify_method):
                        verify_method()
            except Exception as e:
                good = False
                if show_warnings:
                    print(f"Warning: digest check failed for object {node!r}: {e}")

        if good:
            good_objects += 1

        # Recurse into children if any
        children = getattr(node, "children", None)
        if children is None:
            # Fall back to iteration protocol if available
            try:
                iterated = False
                for child in node:
                    if hasattr(child, "children") or hasattr(child, "__iter__"):
                        _walk(child)
                    iterated = True
                if not iterated:
                    return
            except TypeError:
                return
        else:
            for child in children:
                _walk(child)

    _walk(self)
    return num_objects, good_objects

