def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError('`version` must be a string')

    if not version.isdigit():
        raise ValueError('`version` must consist of digits only')

    original_len = len(version)
    try:
        number = int(version)
    except ValueError:
        raise ValueError('`version` cannot be converted to an integer')

    number += 1

    new_version = str(number)
    if len(new_version) < original_len:
        # Preserve leading zeros
        new_version = new_version.zfill(original_len)
    return new_version

