def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os

        # Prepare container for digests that differ from the root inventory
        self.different_digests = {}
        # Keep track of the entries that were present in the previous version
        previous_entries = set()

        # Helper to load an inventory file as a dictionary {filename: digest}
        def _load_inventory(path):
            inventory = {}
            if not os.path.isfile(path):
                raise FileNotFoundError(f"Inventory file missing: {path}")
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    # Detect common formats: 'digest filename' or 'filename digest'
                    if len(parts[0]) == 40:  # rough SHA‑1 length
                        digest, filename = parts
                    else:
                        filename, digest = parts
                    inventory[filename] = digest
            return inventory

        # Ensure we have a root inventory reference. If not yet loaded, attempt to load it.
        if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
            root_inventory_path = os.path.join(self.root_dir, 'inventory')
            if os.path.isfile(root_inventory_path):
                self.root_inventory = _load_inventory(root_inventory_path)
            else:
                self.root_inventory = {}

        # Iterate through all provided version directories in order
        for idx, dirname in enumerate(version_dirs):
            inv_path = os.path.join(dirname, 'inventory')
            current_inventory = _load_inventory(inv_path)

            # Validate that this inventory contains all files from previous versions
            missing_files = previous_entries - set(current_inventory.keys())
            if missing_files and idx > 0:
                msg = f"Version {idx + 1} inventory missing files: {', '.join(sorted(missing_files))}"
                raise ValueError(msg)

            # Record any digest differences compared with the root inventory
            for fname, digest in current_inventory.items():
                root_digest = self.root_inventory.get(fname)
                if root_digest and digest != root_digest:
                    self.different_digests.setdefault(fname, (root_digest, digest))

            # Update the set of files we know about for the next iteration
            previous_entries = set(current_inventory.keys())

