def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path
    try:
        p = Path(path)
    except Exception as e:
        return f'invalid path: {e}'

    if not p.exists():
        return 'path does not exist'

    if p.is_file():
        return 'file'

    if not p.is_dir():
        return 'not a directory'

    # Check for an OCFL Object: directory contains a subdirectory called "0"
    # which in turn contains a file starting with "0=" (a Namaste file)
    for sub in p.iterdir():
        if sub.is_dir() and sub.name == '0':
            for child in sub.iterdir():
                if child.is_file() and child.name.startswith('0='):
                    return 'object'
    # If not an object but has child directories, it is probably a storage root
    if any(child.is_dir() for child in p.iterdir()):
        return 'root'
    # If we get here, it's an empty directory or an unrecognised structure
    return 'unknown directory type'

