def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Basic type checks
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        raise ValueError("bug_ids must not be None")
    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (int, str)):
        ids_str = str(bug_ids)
    else:
        try:
            ids_str = ','.join(str(bid) for bid in bug_ids)
        except Exception as exc:
            raise ValueError("bug_ids must be an int, str or an iterable of them") from exc
    # Bugzilla expects 'ids' for multiple IDs and 'id' for a single ID
    if ',' in ids_str:
        params['ids'] = ids_str
    else:
        params['id'] = ids_str
    return params

