def deep_merge_nodes(nodes):  # pragma: no cover
    """
    Deep-merge a list of YAML node tuples.

    Parameters
    ----------
    nodes : list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        A list of (key, value) tuples where ``key`` is a ScalarNode and
        ``value`` is either a MappingNode or another node type.

    Returns
    -------
    list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        A new list where duplicate keys are merged. For MappingNode values,
        subkeys are recursively merged. For non-MappingNode colliding values,
        the last seen value wins.

    Notes
    -----
    The function assumes that ``MappingNode`` objects expose a ``value`` attribute
    that is a list of (key_node, value_node) tuples and a ``tag`` attribute.
    Other node types are left untouched.
    """
    # Helper that merges two MappingNodes, mutating ``first`` and returning it.
    def _merge_mapping_nodes(first, second):
        # Build dict for fast key lookup in first
        first_map = {k.value: v for k, v in first.value}
        # Iterate over second mapping keys
        for skey, svalue in second.value:
            key = skey.value
            if key in first_map:
                fvalue = first_map[key]
                # If both are mappings, merge recursively
                if hasattr(fvalue, "value") and hasattr(svalue, "value"):
                    if first_map[key].tag.startswith("tag:yaml.org,2002:map"):
                        # Recursively merge
                        _merge_mapping_nodes(first_map[key], svalue)
                        # Ensure order: drop old entry, re-add merged
                        # Remove second entry from first.value list
                        for i, (knode, vnode) in enumerate(first.value):
                            if knode.value == key:
                                first.value[i] = (skey, first_map[key])
                                break
                    else:
                        # Replace non-mapping value with second
                        first_map[key] = svalue
                        for i, (knode, vnode) in enumerate(first.value):
                            if knode.value == key:
                                first.value[i] = (skey, svalue)
                                break
                else:
                    # Non-mapping: replace with second value
                    first_map[key] = svalue
                    for i, (knode, vnode) in enumerate(first.value):
                        if knode.value == key:
                            first.value[i] = (skey, svalue)
                            break
            else:
                # New key: append
                first.value.append((skey, svalue))
                first_map[key] = svalue
        return first

    merged = {}
    key_nodes = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_value = merged[key]
            # If both values are mapping nodes, merge deep
            if hasattr(existing_value, "value") and hasattr(value_node, "value"):
                if existing_value.tag.startswith("tag:yaml.org,2002:map"):
                    merged[key] = _merge_mapping_nodes(existing_value, value_node)
                else:
                    # last wins
                    merged[key] = value_node
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node
            key_nodes[key] = key_node

    # Preserve order as first appearance
    result = []
    seen = set()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append((key_nodes[key], merged[key]))
            seen.add(key)
    return result

