def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    base = len(alphabet)
    # Create a mapping from symbol to its numerical value
    try:
        mapping = {symbol: index for index, symbol in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError("Alphabet must be a list of unique symbols.") from exc

    if not string:
        raise ValueError("Input string must not be empty.")

    value = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"Character '{char}' not found in alphabet.")
        digit = mapping[char]
        value = value * base + digit

    return value

