def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    # Determine whether to use POSIX-style splitting
    if platform == 'this':
        posix = not sys.platform.startswith('win')
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError("Unsupported platform value: %r" % platform)

    # Fast regex-based splitter for POSIX behaviour (used as fallback)
    def _posix_split(text):
        tokens = []
        i = 0
        length = len(text)
        while i < length:
            while i < length and text[i].isspace():
                i += 1
            if i >= length:
                break
            if text[i] in ('"', "'"):
                quote = text[i]
                i += 1
                buf = []
                while i < length:
                    if text[i] == quote:
                        i += 1
                        break
                    if text[i] == '\\' and i + 1 < length:
                        buf.append(text[i + 1])
                        i += 2
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
            else:
                buf = []
                while i < length and not text[i].isspace():
                    if text[i] == '\\' and i + 1 < length:
                        buf.append(text[i + 1])
                        i += 2
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
        return tokens

    # If POSIX, use the regex-based splitter; otherwise, delegate to shlex
    if posix:
        return _posix_split(s)
    else:
        import shlex
        return shlex.split(s, posix=False)

