def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    from subprocess import run, CalledProcessError

    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    destination = Path(tmp_path) / archive.stem
    if destination.exists():
        # If the destination already exists, remove it before extraction
        try:
            if destination.is_dir():
                for child in destination.rglob('*'):
                    if child.is_file():
                        child.unlink()
                    else:
                        child.rmdir()
                destination.rmdir()
            else:
                destination.unlink()
        except Exception as exc:
            raise RuntimeError(f"Failed to clear existing extraction directory '{destination}': {exc}") from exc

    destination.mkdir(parents=True, exist_ok=True)

    try:
        if archive.suffix.lower() == ".zip":
            cmd = ["unzip", "-q", str(archive), "-d", str(destination)]
        else:
            cmd = ["tar", "xf", str(archive), "-C", str(destination)]
        run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except CalledProcessError as e:
        raise RuntimeError(f"Extraction failed for '{archive_path}': {e.stderr.decode().strip()}") from e

    return destination.as_uri()

