def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str):
        raise TypeError(f"config_filename must be a string, got {type(config_filename).__name__}")
    if not isinstance(rendered_config, str):
        raise TypeError(f"rendered_config must be a string, got {type(rendered_config).__name__}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an integer, got {type(mode).__name__}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite).__name__}")

    # Ensure path is absolute for consistency
    config_path = os.path.abspath(config_filename)

    # Abort if file exists and overwrite is False
    if os.path.exists(config_path) and not overwrite:
        raise FileExistsError(f"File '{config_path}' already exists and overwrite is False.")

    # Create parent directories if needed
    parent_dir = os.path.dirname(config_path)
    if parent_dir and not os.path.isdir(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create directories for '{parent_dir}': {exc}") from exc

    # Write the rendered configuration
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
    except Exception as exc:
        raise IOError(f"Failed to write configuration to '{config_path}': {exc}") from exc

    # Set the file permissions
    try:
        os.chmod(config_path, mode)
    except Exception as exc:
        # Permission error typically only occurs if the user does not have rights
        raise OSError(f"Failed to set permissions on '{config_path}': {exc}") from exc

    return config_path

