def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Validate inputs
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of arguments")

    # Build the command list
    if isinstance(commands, list):
        if not commands:
            raise ValueError("commands list cannot be empty")
        command = commands + args
    else:
        command = [commands] + args

    # Debug output if requested
    if verbose:
        cmd_str = ' '.join(f"'{arg}'" if ' ' in arg else arg for arg in command)
        print(f"Running command: {cmd_str}")

    # Prepare subprocess arguments
    subprocess_kwargs = {"cwd": cwd, "text": True, "check": True}
    if env is not None:
        subprocess_kwargs["env"] = env
    if hide_stderr:
        subprocess_kwargs["stderr"] = subprocess.DEVNULL

    try:
        result = subprocess.run(command, **subprocess_kwargs)
        return result
    except subprocess.CalledProcessError as exc:
        # Re-raise with a clearer message
        errmsg = f"Command '{' '.join(command)}' exited with code {exc.returncode}"
        raise subprocess.CalledProcessError(exc.returncode, exc.cmd, exc.output, errmsg) from exc
    except Exception as exc:
        # Catch-all for unforeseen errors
        raise RuntimeError(f"Failed to run command '{' '.join(command)}': {exc}") from exc

