    """Dump to a py2-unicode or py3-string"""
    try:
        # Use safe_dump by default for security; if a dumper is given, use it
        if dumper is None:
            s = yaml.safe_dump(obj, allow_unicode=True, default_flow_style=False, sort_keys=False)
        else:
            s = yaml.dump(obj, Dumper=dumper, allow_unicode=True, default_flow_style=False, sort_keys=False)

        # Ensure we return a text type (unicode in py2, str in py3)
        if isinstance(s, (bytes, bytearray)):
            try:
