def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Validate new scale value
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric.")
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        # Assuming LenaValueError is defined elsewhere in the module
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale each field's last coordinate and associated errors
    fields = getattr(self, "fields", None)
    if fields is None:
        # Attempt to guess common attribute names for fields
        if hasattr(self, "grid"):
            fields = getattr(self, "grid")
        else:
            fields = []

    for field in fields or []:
        # Rescale data points
        # Common containers might be numpy arrays or lists of tuples
        # Attempt to find numeric arrays
        data = None
        if hasattr(field, "data"):
            data = field.data
        elif hasattr(field, "points"):
            data = field.points
        if data is None:
            continue

        try:
            import numpy as np
            if isinstance(data, np.ndarray):
                # Ensure array has at least one dimension
                if data.ndim >= 1:
                    data[:, -1] *= factor
                if hasattr(field, "errors") and field.errors is not None:
                    if isinstance(field.errors, np.ndarray):
                        field.errors[:, -1] *= factor
                    elif isinstance(field.errors, list):
                        for err in field.errors:
                            if hasattr(err, "__iter__"):
                                err[-1] *= factor
            else:
                # Assume data is list-like of tuples or lists
                new_points = []
                for pt in data:
                    pt = list(pt)
                    pt[-1] *= factor
                    new_points.append(tuple(pt))
                if hasattr(field, "points"):
                    field.points = new_points
                # Rescale errors if present
                if hasattr(field, "errors") and field.errors is not None:
                    new_errors = []
                    for err in field.errors:
                        err = list(err)
                        err[-1] *= factor
                        new_errors.append(tuple(err))
                    field.errors = new_errors
        except Exception:
            # If any custom field implementation fails, skip silently
            continue

    # Update the graph's scale
    self._scale = other
    return None

