    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Helper to recursively verify a sequence of interfaces
    def _verify_sequence(seq, cand):
        for sub in seq:
            if not verifyClass(sub, cand, tentative=True):
                raise ValueError(f"Candidate {cand!r} does not satisfy interface {sub!r}")
