def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Helper to pick the most derived metaclass between two candidates
    def _most_specific_meta(meta1, meta2):
        if issubclass(meta1, meta2):
            return meta1
        if issubclass(meta2, meta1):
            return meta2
        raise TypeError(
            f"Cannot create class with metaclass {meta1.__name__} "
            f"and {meta2.__name__} because they are not compatible."
        )

    if not bases:
        raise TypeError("determineMetaclass requires at least one base class")

    # Start with the metaclass of the first base or the explicit one if provided
    candidate = explicit_mc or type(bases[0])

    # Determine the most derived metaclass among all bases
    for base in bases[1:]:
        candidate = _most_specific_meta(candidate, type(base))

    # If an explicit metaclass was provided, ensure compatibility and pick the more derived
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        if not issubclass(candidate, explicit_mc) and not issubclass(explicit_mc, candidate):
            raise TypeError(
                f"metaclass conflict: {candidate.__name__} and {explicit_mc.__name__} are not compatible"
            )
        candidate = _most_specific_meta(candidate, explicit_mc)

    return candidate

