def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # If a frequency map is maintained on this dict, use it to find the least used key.
    freq_map = getattr(self, "_freq", None)
    # If we do not have a frequency map, fall back to the default behavior of a dict.
    if freq_map is None:
        return super(type(self), self).popitem()
    # Find the key with the smallest frequency. If frequencies are equal, the
    # earliest key will be returned, mimicking stable ordering for ties.
    try:
        key = min(self.keys(), key=lambda k: freq_map.get(k, 0))
    except ValueError:
        # This should not happen because we already checked the dict is non-empty.
        raise KeyError('dictionary is empty')
    value = self.pop(key)
    freq_map.pop(key, None)
    return key, value

