        if getattr(request, "is_public", False) is True:
            return True
        if getattr(request, "public", False) is True:
            return True
    except Exception:
        # In case any evaluator fails – ignore and continue
        pass

    # Now check for a private message
    try:
        if getattr(request, "is_private", False) is True:
            return True
        if getattr(request, "private", False) is True:
            return True
    except Exception:
        pass

    # Finally, attempt to detect a legacy payload
    try:
        # Check for known legacy key in the payload
        payload = getattr(request, "payload", None)
        if isinstance(payload, dict):
            # Legacy payloads often contain one of these markers
            if "legacy" in payload or "old_format" in payload:
