def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("Provided node is None")
    # Attempt to iterate over direct children
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("Provided node does not support iteration over children") from exc

    result = {}
    for child in children:
        # For ElementTree elements, tag is a string.
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue  # skip non-element nodes
        result[tag] = child
    return result

