def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation: url must contain scheme
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Normalise base url: strip trailing slash to avoid double slashes
    base = url.rstrip("/")
    if document_path is None:
        # Default NodeInfo 2.0 document path
        document_path = "/.well-known/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        if not document_path.startswith("/"):
            document_path = "/" + document_path

    full_href = base + document_path

    # Construct minimal NodeInfo .well-known document
    return {
        "@context": "https://www.w3.org/ns/nodeinfo",
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/1.0",
                "href": full_href
            },
            {
                "rel": "self",
                "href": full_href
            }
        ]
    }

