def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message."""
    try:
        # Resolve the signature element: it may already be an Element
        if isinstance(signature, (bytes, str)):
            try:
                from lxml import etree
                sig_root = etree.fromstring(signature)
            except Exception as exc:
                raise ValueError("Signature string could not be parsed as XML") from exc
        else:
            sig_root = signature
        # Ensure we have a key
        if not public_key:
            raise ValueError("Public key is required for verification")
        # Load the key via xmlsec
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        ctx = xmlsec.SignatureContext()
        ctx.key = key
        # Register the ID attribute of the signed data (commonly 'Id')
        try:
            ctx.register_id(doc, "Id")
        except Exception:
            # ignore if registration fails (ID may not be present)
            pass
        # Perform verification: this will raise xmlsec.VerificationError on failure
        ctx.verify(sig_root)
        return True
    except Exception:
        return False

