def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve (e.g., 'user@pod.example.com' or 'acct:user@pod.example.com')
    :returns: dict representing the JSON webfinger document
    :raises ValueError: if the handle is invalid or the document cannot be retrieved/parsed
    """
    import urllib.request
    import urllib.parse
    import json
    from urllib.error import HTTPError, URLError

    if not isinstance(handle, str) or not handle.strip():
        raise ValueError("handle must be a non-empty string")

    # Normalize handle to include 'acct:' prefix if missing
    if not handle.startswith("acct:"):
        resource = f"acct:{handle}"
    else:
        resource = handle

    # Extract domain from handle (after '@')
    try:
        _local, domain = handle.split("@", 1)
    except ValueError:
        raise ValueError(f"Invalid handle format: '{handle}'. Expected format 'user@domain'")

    # Construct the webfinger URL
    query = urllib.parse.urlencode({"resource": resource})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            raw_data = response.read()
    except HTTPError as e:
        raise ValueError(f"HTTP error {e.code} when accessing {url}") from e
    except URLError as e:
        raise ValueError(f"Failed to reach {url}: {e.reason}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error when retrieving webfinger from {url}") from e

    try:
        decoded = raw_data.decode("utf-8")
    except Exception as e:
        raise ValueError("Failed to decode webfinger response as UTF-8") from e

    try:
        return json.loads(decoded)
    except json.JSONDecodeError as e:
        raise ValueError("Failed to parse webfinger JSON") from e

