def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    Returns a sorted list of file paths from the given directories that end with the
    supplied spec_option (default: '.ini'). Directories that cannot be accessed
    are ignored, and any non‑string entries in `settings_dirs` are skipped.
    Arguments:
        settings_dirs (Iterable[str]): Sequence of directory paths to search.
        spec_option (str): File extension pattern to filter on, e.g. '.ini' or 'txt'.
    Returns:
        List[str]: Sorted list of matching file paths.
    Raises:
        ValueError: If spec_option is not a string or if settings_dirs is not iterable.
    """
    import os

    # Validate inputs
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")
    try:
        iter(settings_dirs)
    except TypeError:
        raise ValueError("settings_dirs must be an iterable of path strings")

    # Normalise spec_option to include a leading dot only if missing
    if spec_option and not spec_option.startswith('.'):
        spec_option = f".{spec_option}"

    file_list = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            # Skip non-string entries silently
            continue
        try:
            if not os.path.isdir(dir_path):
                # Skip if not a directory
                continue
            for fname in os.listdir(dir_path):
                full_path = os.path.join(dir_path, fname)
                if os.path.isfile(full_path):
                    if not spec_option or fname.lower().endswith(spec_option.lower()):
                        file_list.append(full_path)
        except OSError:
            # Unable to access directory – skip it and continue
            continue

    return sorted(file_list)

