def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    from collections import OrderedDict

    # Helper exception in case not defined elsewhere
    try:
        IRValidatorException  # noqa: F401
    except NameError:
        class IRValidatorException(Exception):
            pass

    # Load YAML if a string was supplied
    if spec_content is None:
        raise IRValidatorException("Specification content cannot be None")

    # If it's a string, attempt to parse as YAML
    if isinstance(spec_content, (str, bytes)):
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Unable to parse YAML content: {exc}") from exc
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException(f"Unsupported type for spec_content: {type(spec_content).__name__}")

    if not isinstance(data, dict):
        raise IRValidatorException("Specification content must resolve to a mapping")

    # Define mandatory fields that every spec should contain
    # Adjust this list as per actual requirements
    mandatory_fields = ["title", "version", "author"]

    missing = [field for field in mandatory_fields if field not in data]
    if missing:
        missing_str = ", ".join(missing)
        raise IRValidatorException(f"Missing mandatory field(s) in spec: {missing_str}")

    # All checks passed, return the loaded dictionary
    return data

