def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Use a recursive resolver with a visited set to prevent circular references.
    visited = set()

    def _resolve_group(group_name):
        """Recursively resolve a single group, merging includes."""
        if group_name in visited:
            # Circular reference detected; stop recursion.
            raise ValueError(f"Circular include detected for group '{group_name}'")
        visited.add(group_name)

        if group_name not in parser_dict:
            raise KeyError(f"Included group '{group_name}' not present in parser_dict")

        group_def = parser_dict[group_name]
        if not isinstance(group_def, dict):
            raise TypeError(f"Group definition for '{group_name}' must be a dict")

        # Create a copy so that we don't mutate the original parser_dict.
        merged = {}

        # Handle include directive; it may be a single name or a list of names.
        include = group_def.pop('include', None)
        if include:
            if isinstance(include, str):
                include = [include]
            if not isinstance(include, (list, tuple)):
                raise TypeError(f"'include' directive for group '{group_name}' must be a string or a list of strings")

            for inc in include:
                merged.update(_resolve_group(inc))

        # Merge the remaining keys of the current group, overwriting any duplicates.
        merged.update(group_def)
        return merged

    # Resolve all groups in the dictionary.
    resolved_dict = {}
    for gname in parser_dict:
        resolved_dict[gname] = _resolve_group(gname)

    return resolved_dict

