def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to the new argument name
    deprecation_map = getattr(self, 'DEPRECATED_ARGS', {})

    # Helper to process a single args dictionary
    def _process(arg_dict):
        for key in list(arg_dict):
            if key in deprecation_map:
                new_name = deprecation_map[key]
                message = f"Argument '{key}' is deprecated."
                if new_name:
                    message += f" Use '{new_name}' instead."
                # Prefer a logger if available, otherwise fallback to print
                if hasattr(self, 'logger') and hasattr(self.logger, 'warning'):
                    self.logger.warning(message)
                else:
                    print(message)

                # If a replacement name exists, forward the value
                if new_name:
                    if new_name in arg_dict:
                        # Avoid accidental overwrite; keep existing value
                        pass
                    else:
                        arg_dict[new_name] = arg_dict.pop(key)
                else:
                    # Just remove the deprecated argument
                    arg_dict.pop(key)

    # Validate CLI and answer file arguments
    _process(cli_args)
    _process(answer_file_args)

