def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string, got %r" % (command_name,))

    # First try a direct mapping stored on this object
    try:
        specs_map = getattr(self, "command_specs", None)
        if specs_map and command_name in specs_map:
            return list(specs_map[command_name])
    except Exception:
        # Ignore any errors from the mapping and fall back
        pass

    # Fallback to a parser object that might have a commands dict
    try:
        parser = getattr(self, "parser", None)
        if parser:
            commands = getattr(parser, "commands", None)
            if commands:
                cmd_obj = commands.get(command_name)
                if cmd_obj:
                    # Assume the command object has an 'options' attribute
                    options = getattr(cmd_obj, "options", None)
                    if options:
                        return list(options)
    except Exception:
        # If anything goes wrong in the fallback, just return an empty list
        pass

    # If all lookups fail, return an empty list
    return []

