def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")
    try:
        cmd = self.commands[command_name]
    except Exception:
        raise ValueError(f"Unknown command: {command_name!r}")
    # The command's options lookup
    options = cmd.get("options")
    if options is None:
        raise ValueError(f"Command {command_name!r} has no options defined")
    spec = None
    if isinstance(options, dict):
        spec = options.get(argument_name)
    elif isinstance(options, list):
        for opt in options:
            if isinstance(opt, dict) and opt.get("name") == argument_name:
                spec = opt
                break
    if spec is None:
        raise ValueError(f"Option {argument_name!r} not found in command {command_name!r}")
    return spec

