    # we simply skip validation.
    try:
        min_val = getattr(self, "min", None)
        max_val = getattr(self, "max", None)
    except Exception as exc:
        raise ValueError("Unable to obtain min/max bounds") from exc

    if min_val is None or max_val is None:
        return

    # Flexible handling of the incoming arguments.
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for val in values:
