def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        try:
            flat_args = {}
            if args is None:
                flat_args = {}
            elif isinstance(args, dict):
                flat_args = args
            elif isinstance(args, (list, tuple)):
                for item in args:
                    if isinstance(item, dict):
                        flat_args.update(item)
                    elif isinstance(item, (list, tuple)) and len(item) == 2:
                        flat_args[item[0]] = item[1]
                    elif isinstance(item, str):
                        if '=' in item:
                            key, value = item.split('=', 1)
                            flat_args[key] = value
                        else:
                            # Treat lone string as key with True value
                            flat_args[item] = True
                    else:
                        raise ValueError(f"Unsupported argument item type: {type(item)}")
            else:
                raise ValueError(f"Argument must be dict or list/tuple, got {type(args)}")

            for key, value in flat_args.items():
                if isinstance(key, str) and key.startswith('control_'):
                    control_args[key[len('control_') :]] = value
                else:
                    nested_args[key] = value
        except Exception as exc:
            raise ValueError(f"Failed to parse arguments: {exc}") from exc

        return control_args, nested_args

