def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the basic command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity options (-v, -vv, ... up to 5 levels)
    if verbose:
        try:
            level = int(verbose)
        except Exception:
            level = 1
        # Keep verbosity to a reasonable max to avoid accidental over-verbosity
        level = max(1, min(level, 5))
        cmd.extend(["-v" * level])

    # Handle extra_vars: Ansible expects key=value or JSON
    if extra_vars:
        try:
            import json
            # Pass as a JSON string via --extra-vars
            json_str = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", json_str])
        except Exception:
            # Fallback to simple key=value
            for k, v in extra_vars.items():
                cmd.extend(["-e", f"{k}={v}"])

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for k, v in ansible_args.items():
            # Arguments that are flags without values
            if v is True:
                cmd.append(k)
            elif v is False or v is None:
                continue
            else:
                # Value may be a list of items
                if isinstance(v, (list, tuple)):
                    for item in v:
                        cmd.extend([k, str(item)])
                else:
                    cmd.extend([k, str(v)])

    # Let plugin handle any debugging or logging
    if ir_plugin:
        try:
            log = getattr(ir_plugin, "logger", None)
            if log:
                log.debug(f"Running ansible-playbook with command: {' '.join(cmd)}")
        except Exception:
            pass

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
        # On success we can return the CompletedProcess object
        return result
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook not found. Make sure Ansible is installed and in PATH.") from e
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}") from e

